/* Extract the text between the first and the last '"' of the line. */
static int quoted_arg(const char *line, char *out, size_t cap)
{
    const char *a = strchr(line, '"');
    const char *b = strrchr(line, '"');
    if (!a || a == b) return 0;
    size_t n = (size_t)(b - a - 1);
    if (n >= cap) n = cap - 1;
    memcpy(out, a + 1, n);
    out[n] = '\0';
    return 1;
}

