#include <stddef.h>

size_t remove_duplicates(char *s)
{
    unsigned char seen[256] = {0};
    size_t w = 0;

    if (s == NULL)
        return 0;

    for (size_t r = 0; s[r] != '\0'; r++) {
        unsigned char c = (unsigned char)s[r];   /* never index with a signed char */
        if (!seen[c]) {
            seen[c] = 1;
            s[w++] = s[r];                       /* w <= r: safe in place */
        }
    }
    s[w] = '\0';
    return w;
}

