/* Build "<ecu>:<dtc>" on the heap, e.g. "BCM:U0100". The caller frees it. */
static char *make_tag(const char *ecu, const char *dtc)
{
    size_t len = strlen(ecu) + strlen(dtc) + 1;     /* +1 for the ':' separator */
    char *tag = malloc(len);
    if (tag == NULL)
        return NULL;

    strcpy(tag, ecu);
    strcat(tag, ":");
    strcat(tag, dtc);
    return tag;
}

