    for (int i = 0; i < n; i++) {
        char ecu[32], dtc[16];
        if (scanf("%31s %15s", ecu, dtc) != 2) break;

        char *tag = make_tag(ecu, dtc);
        if (tag == NULL) return 1;
        printf("%s (%zu)\n", tag, strlen(tag));
        free(tag);
    }
    return 0;
}

