solution_code:
#include <limits.h>
#include <stddef.h>

int my_atoi(const char *s, int *err)
{
    int value = 0;
    int e = 1;          /* "no digits" until we see one */
    int neg = 0;

    if (s == NULL) {
        if (err) *err = 1;
        return 0;
    }
    while (*s == ' ' || (*s >= '\t' && *s <= '\r'))   /* \t \n \v \f \r */
        s++;
    if (*s == '+' || *s == '-') {
        neg = (*s == '-');
        s++;
    }
    for (; *s >= '0' && *s <= '9'; s++) {
        int d = *s - '0';
        if (e == 1)
            e = 0;                      /* at least one digit */
        if (e == 2)
            continue;                   /* already clamped: just consume */
        if (!neg) {
            if (value > (INT_MAX - d) / 10) {
                value = INT_MAX;
                e = 2;
            } else {
                value = value * 10 + d;
            }
        } else {
            /* accumulate as a NEGATIVE number so INT_MIN is reachable */
            if (value < (INT_MIN + d) / 10) {
                value = INT_MIN;
                e = 2;
            } else {
                value = value * 10 - d;
            }
        }
    }
    if (err) *err = e;
    return value;
}

