#include <stddef.h>

size_t rle_compress(char *s)
{
    size_t r = 0, w = 0;

    if (s == NULL)
        return 0;

    while (s[r] != '\0') {
        char c = s[r];
        size_t k = 0;
        while (s[r] == c) {         /* measure the whole run first */
            r++;
            k++;
        }
        s[w++] = c;
        if (k >= 2) {
            char tmp[24];
            size_t n = 0;
            while (k > 0) {         /* digits come out LSB-first */
                tmp[n++] = (char)('0' + k % 10);
                k /= 10;
            }
            while (n > 0)
                s[w++] = tmp[--n];  /* 1 + digits(k) <= k, so w <= r */
        }
    }
    s[w] = '\0';
    return w;
}

