#define MAX_ROUTES 32

/* "0x100:1,2" -> prints "0x100 -> 1 2" */
static void parse_route(char *route)
{
    char *id = strtok(route, ":");
    if (id == NULL)
        return;
    printf("0x%03X ->", (unsigned int)strtoul(id, NULL, 16));
    for (char *ch = strtok(NULL, ","); ch != NULL; ch = strtok(NULL, ","))
        printf(" %d", atoi(ch));
    putchar('\n');
}

int main(void)
{
    char line[512];
