    if (!fgets(line, sizeof line, stdin) || sscanf(line, "%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        if (!fgets(line, sizeof line, stdin)) line[0] = '\0';
        line[strcspn(line, "\r\n")] = '\0';

        for (char *r = strtok(line, ";"); r != NULL; r = strtok(NULL, ";"))
            parse_route(r);
        puts("--");
    }
    return 0;
}

